"""Read-only timeline projection of original outcomes, without copying supplier threads."""

from datetime import UTC, datetime

from .models import timestamp


def _supplier_name(supplier_id, threads):
    if not supplier_id:
        return 'No selection / unknown'
    thread = threads.get(supplier_id, {})
    if not isinstance(thread, dict):
        return supplier_id
    messages = thread.get('messages', thread.get('thread', []))
    if isinstance(messages, list):
        for message in messages:
            if isinstance(message, dict) and message.get('from') != 'buyer':
                name = message.get('from_name')
                if isinstance(name, str) and name.strip():
                    return name[:200]
    return supplier_id


def _point(attempt, **metadata):
    result = attempt.get('result') or {}
    supplier_id = result.get('supplier_id')
    if not isinstance(supplier_id, str) or not supplier_id.strip():
        supplier_id = None
    value = attempt.get('score')
    valid = attempt.get('status') == 'completed' and type(value) in (int, float) and 0 <= value <= 1
    if metadata['source'] == 'campaign' and result.get('ended') is not True:
        valid = False
    return dict(
        **metadata, attempt_id=attempt['attempt_id'], case_id=attempt['case_id'],
        session_id=attempt.get('session_id'), supplier_id=supplier_id,
        supplier_name=_supplier_name(supplier_id, attempt.get('threads') or {}),
        score=value * 100 if valid else None, status=attempt['status'],
        deal=result.get('deal'), timeouts=attempt.get('timeouts'),
    )


def score_history(store, loop_store):
    """Keep each session once, preferring its original campaign/tracked owner over imports."""
    points = []
    for run in store.all():
        for attempt in run.attempts:
            if attempt.status == 'pending':
                continue
            points.append(_point(
                attempt.model_dump(), id=f'run:{run.run_id}:{attempt.attempt_id}',
                run_id=run.run_id, campaign_id=None, name=run.name, source=run.source,
                author=run.author, environment=run.environment, arena_url=run.arena_url,
                timestamp=run.started_at, time_basis='session_start' if run.source == 'imported' else 'run_start',
                commit=run.provenance.commit if run.source == 'tracked' and run.provenance else None,
                dirty=run.provenance.dirty if run.source == 'tracked' and run.provenance else None,
                checkpoint_id=None, arm=None,
            ))
    # One SQLite snapshot keeps campaign and checkpoint metadata consistent during uploads.
    with loop_store._connect() as db:
        db.execute('BEGIN')
        suites = {s['suite_id']: s for s in loop_store._all(db, 'suites') if 'suite_id' in s}
        checkpoints = {c['checkpoint_id']: c for c in loop_store._all(db, 'checkpoints') if 'checkpoint_id' in c}
        # Read by record identity too, for older metadata with no embedded identifier.
        for campaign in loop_store._all(db, 'campaigns'):
            suite = suites.get(campaign['suite_id']) or loop_store._get(db, 'suites', campaign['suite_id'])
            for attempt in campaign['attempts']:
                if attempt['status'] == 'pending':
                    continue
                checkpoint_id = attempt.get('checkpoint_id')
                checkpoint = checkpoints.get(checkpoint_id)
                if checkpoint is None and checkpoint_id:
                    checkpoint = loop_store._get(db, 'checkpoints', checkpoint_id)
                started = attempt.get('start', {}).get('started_at', campaign['created_at'])
                points.append(_point(
                    attempt, id=f"campaign:{attempt['attempt_id']}", run_id=None,
                    campaign_id=campaign['campaign_id'], name=campaign['campaign_id'], source='campaign',
                    author=campaign.get('author'), environment=suite['environment'], arena_url=suite['arena_url'],
                    timestamp=datetime.fromtimestamp(started, UTC).isoformat(),
                    time_basis='attempt_start' if 'start' in attempt else 'campaign_start',
                    commit=(checkpoint or {}).get('commit'), dirty=False, checkpoint_id=checkpoint_id,
                    arm=attempt.get('arm'),
                ))
    unique = {}
    priority = {'imported': 0, 'tracked': 1, 'campaign': 2}
    for point in sorted(points, key=lambda p: (priority[p['source']], p['id'])):
        key = (point['arena_url'].rstrip('/'), point['session_id']) if point['session_id'] else point['id']
        unique[key] = point
    return {'points': sorted(unique.values(), key=lambda p: (timestamp(p['timestamp']), p['id']))}
